
import { GRSymbolView } from '../../slots/GRSymbolView';
import { GCSymbolEvent, ICascadeSymbolData } from './types';

export abstract class GCSymbolView extends GRSymbolView {

    public eventFire: GCSymbolEvent;
    public symbolData: ICascadeSymbolData;

    constructor() {
        super();
        this.addEvents();
        this.addDataStructures();
    }

    public removeFromCascade(): void {
        this.alpha = 0;
        this.eventFire.symbolEvent.REMOVE_FROM_CASCADE();
    }

    public returnToCascade(): void {
        this.symbolData.removedFromCascade = false;
        this.alpha = 1;
    }

    public onCascadeLand(): void {
        // can be overridden in the implementing class
        // this is triggered on each block when it lands from a cascade
    }

    private addDataStructures(): void {
        // add cascade data structure to symbolData
        Object.assign(this.symbolData, { removeFromCascade: false });
    }

    private addEvents(): void {
        // add cascade events to eventfire
        Object.assign(this.eventFire.symbolEvent, { REMOVE_FROM_CASCADE: () => { return; } });
    }
}
